"""« Que visiter » : pays d'Afrique ajoutés le 13 novembre 2026 (Mali, Guinée, Bénin, Togo, Burkina Faso, RD Congo, Gabon, Nigeria).
Les trois langues sont écrites ici, lieu par lieu : (clé, type, nom fr, texte fr, nom en, texte en, nom it, texte it).
Mêmes règles que scripts/visiter.py : aucun prix, aucune règle de visa, de santé ou de sécurité ; un lieu sans vraie photo n'est pas publié."""


def _pays(cc, flag, air, fr, en, it, lieux):
    """fr, en, it : (slug, nom, « au Mali », ville, accroche)"""
    P = dict(cc=cc, slug=fr[0], nom=fr[1], en=fr[2], flag=flag, air=air, ville=fr[3], region="Afrique", accroche=fr[4],
             lieux=[dict(key=f"{cc}-{l[0]}", nom=l[2], kind=l[1], txt=l[3]) for l in lieux])
    T = {}
    for lang, d, i in (("en", en, 4), ("it", it, 6)):
        T[lang] = (dict(slug=d[0], nom=d[1], en=d[2], ville=d[3], accroche=d[4]), {f"{cc}-{l[0]}": (l[i], l[i + 1]) for l in lieux})
    return P, T


